def investigate(context, acquire):
    history = acquire("history")
    query_actions = context["actions"]
    goal = context["goal"]

    def simulate(actions, put_op, instr, chan_type):
        committed = {}
        main = {"in_transaction": False, "uncommitted": {}, "total_changes": 0, "last_changes": 0}
        other = {"in_transaction": False, "uncommitted": {}, "total_changes": 0, "last_changes": 0}
        for action in actions:
            op = action["op"]
            conn_name = action.get("connection", "main")
            conn = main if conn_name == "main" else other
            if op == "begin":
                conn["in_transaction"] = True
            elif op == "commit":
                for k, v in conn["uncommitted"].items():
                    if v is None:
                        if k in committed:
                            del committed[k]
                    else:
                        committed[k] = v
                conn["uncommitted"] = {}
                conn["in_transaction"] = False
            elif op == "rollback":
                conn["uncommitted"] = {}
                conn["in_transaction"] = False
            else:
                key = action["key"]
                if key in conn["uncommitted"]:
                    eff_val = conn["uncommitted"][key]
                    exists = eff_val is not None
                elif key in committed:
                    eff_val = committed[key]
                    exists = True
                else:
                    eff_val = None
                    exists = False
                direct = 0
                total_inc = 0
                trigger = False
                if op == "put":
                    val = action["value"]
                    if put_op == "ignore":
                        if not exists:
                            direct = 1
                            total_inc = 1
                            trigger = True
                            new_val = val
                        else:
                            new_val = eff_val
                    elif put_op == "replace":
                        if exists:
                            direct = 1
                            total_inc = 2
                            trigger = True
                            new_val = val
                        else:
                            direct = 1
                            total_inc = 1
                            trigger = True
                            new_val = val
                    else:  # update
                        if exists:
                            direct = 1
                            total_inc = 1
                            trigger = False
                            new_val = val
                        else:
                            direct = 1
                            total_inc = 1
                            trigger = True
                            new_val = val
                elif op == "update":
                    if exists:
                        direct = 1
                        total_inc = 1
                        new_val = action["value"]
                    else:
                        direct = 0
                        total_inc = 0
                        new_val = None
                elif op == "delete":
                    if exists:
                        direct = 1
                        total_inc = 1
                        new_val = None
                    else:
                        direct = 0
                        total_inc = 0
                        new_val = None
                if instr and trigger:
                    total_inc += 1
                conn["total_changes"] += total_inc
                conn["last_changes"] = direct
                if op == "put" or op == "update" or op == "delete":
                    if conn["in_transaction"]:
                        conn["uncommitted"][key] = new_val
                    else:
                        if new_val is None:
                            if key in committed:
                                del committed[key]
                        else:
                            committed[key] = new_val
        if chan_type == "main_changes":
            channel = main["last_changes"]
        elif chan_type == "main_total":
            channel = main["total_changes"]
        else:
            channel = main["total_changes"] + other["total_changes"]
        count = len(committed)
        total_sum = sum(committed.values())
        return channel, count, total_sum

    put_ops = ["ignore", "replace", "update"]
    instrs = [False, True]
    chan_types = ["main_changes", "main_total", "sum_total"]
    consistent = []
    for put_op in put_ops:
        for instr in instrs:
            for chan_type in chan_types:
                ok = True
                for receipt in history:
                    ch, cnt, sm = simulate(receipt["actions"], put_op, instr, chan_type)
                    obs = receipt["observed"]
                    if ch != obs["channel"] or cnt != obs["committed_count"] or sm != obs["committed_sum"]:
                        ok = False
                        break
                if ok:
                    consistent.append((put_op, instr, chan_type))
    if not consistent:
        return {"value": None, "unresolved": True}
    results = []
    for put_op, instr, chan_type in consistent:
        ch, cnt, sm = simulate(query_actions, put_op, instr, chan_type)
        if goal == "channel":
            results.append(ch)
        elif goal == "committed_count":
            results.append(cnt)
        else:
            results.append(sm)
    if all(r == results[0] for r in results):
        return {"value": results[0], "unresolved": False}
    else:
        return {"value": None, "unresolved": True}

